  if (!obj) return obj;
  const keys = Object.keys(obj) as (keyof T)[];
  const result = {} as T;

  for (const key of keys) {
    const camelKey = key[0].toLowerCase() + key.slice(1);
    (result as any)[camelKey] = obj[key];
  }

  return result;
}
